177	      // The KN-NNNN return value of nextId() is intentionally discarded here —
178	      // display-format IDs are produced by MCP tool layer consumers, not stored.
179	      const numericId = store.next_id;
180	      this.nextId(store);
181	
182	      const insight: Insight = InsightSchema.parse({ ...input, id: numericId });
183	      store.insights.push(insight);
184	      store.last_updated = now();
