208	   */
209	  async searchInsights(
210	    query: string,
211	    filters?: {
212	      scope?: InsightScope;
213	      repository_name?: string;
214	      category?: string;
215	      tags?: string[];
216	      limit?: number;
217	      offset?: number;
218	    }
219	  ): Promise<Insight[]> {
220	    const { tags: tagFilter, limit, offset = 0, ...loadFilters } = filters ?? {};
221	
222	    const allInsights = await this._loadInsights(loadFilters);
223	    const q = query.toLowerCase();
224	
225	    let results = allInsights.filter(
226	      (insight) =>
227	        insight.title.toLowerCase().includes(q) ||
228	        insight.content.toLowerCase().includes(q) ||
229	        insight.tags.some((tag) => tag.toLowerCase().includes(q))
230	    );
231	
232	    if (tagFilter && tagFilter.length > 0) {
233	      results = results.filter((insight) =>
234	        tagFilter.every((tag) => insight.tags.includes(tag))
235	      );
236	    }
237	
238	    return results.slice(offset, limit !== undefined ? offset + limit : undefined);
239	  }
